<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$pageTitle='Stock Purchases';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$supplier=(int)($_POST['supplier_id']??0)?:null;$ref=trim((string)($_POST['reference_no']??''));$ids=$_POST['product_id']??[];$qtys=$_POST['quantity']??[];$costs=$_POST['unit_cost']??[];if(!is_array($ids)||!$ids)throw new RuntimeException('Add at least one purchase item.');$pdo->beginTransaction();$lines=[];$total=0;$lock=$pdo->prepare('SELECT id,name,stock_qty FROM products WHERE id=? AND active=1 FOR UPDATE');foreach($ids as $i=>$rawId){$id=(int)$rawId;$qty=(float)($qtys[$i]??0);$cost=(float)($costs[$i]??0);if($id<=0||$qty<=0||$cost<0)continue;$lock->execute([$id]);$p=$lock->fetch();if(!$p)throw new RuntimeException('A selected product is unavailable.');$lines[]=['p'=>$p,'qty'=>$qty,'cost'=>$cost,'sub'=>round($qty*$cost,2)];$total+=round($qty*$cost,2);}if(!$lines)throw new RuntimeException('Enter valid quantities and costs.');$pdo->prepare('INSERT INTO purchases(supplier_id,reference_no,total_amount,received_by) VALUES(?,?,?,?)')->execute([$supplier,$ref?:null,$total,$_SESSION['user_id']]);$purchaseId=(int)$pdo->lastInsertId();foreach($lines as $line){$p=$line['p'];$pdo->prepare('INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_cost,subtotal) VALUES(?,?,?,?,?)')->execute([$purchaseId,$p['id'],$line['qty'],$line['cost'],$line['sub']]);$pdo->prepare('UPDATE products SET stock_qty=stock_qty+?,cost_price=? WHERE id=?')->execute([$line['qty'],$line['cost'],$p['id']]);$pdo->prepare("INSERT INTO inventory_movements(product_id,user_id,movement_type,quantity_change,reference_type,reference_id,notes) VALUES(?,?,'purchase',?,'purchase',?,'Stock purchase received')")->execute([$p['id'],$_SESSION['user_id'],$line['qty'],$purchaseId]);}$pdo->commit();log_action($pdo,'create','purchase',$purchaseId,$ref);flash('success','Purchase recorded and inventory updated.');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();flash('error',$ex instanceof PDOException?'Could not record purchase.':$ex->getMessage());}header('Location: purchases.php');exit;}
$products=$pdo->query('SELECT id,name,sku,unit,cost_price FROM products WHERE active=1 ORDER BY name')->fetchAll();$suppliers=$pdo->query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();$purchases=$pdo->query('SELECT p.*,s.name supplier,u.name receiver FROM purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id JOIN users u ON u.id=p.received_by ORDER BY p.id DESC LIMIT 100')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="dashboard-grid"><div class="panel"><div class="panel-heading"><div><h3>Record stock purchase</h3><p>Receiving stock increases available inventory.</p></div></div><form method="post" id="purchaseForm"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="form-grid two-col"><div class="field"><label>Supplier</label><select name="supplier_id"><option value="">Not specified</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Reference / invoice no.</label><input name="reference_no" maxlength="80"></div></div><div id="purchaseLines" class="purchase-lines"><div class="purchase-line"><select name="product_id[]" required><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>" data-cost="<?= e((string)$p['cost_price']) ?>"><?= e($p['name']) ?><?= $p['sku']?' · '.e($p['sku']):'' ?></option><?php endforeach; ?></select><input type="number" name="quantity[]" min="0.001" step="0.001" placeholder="Qty" required><input type="number" name="unit_cost[]" min="0" step="0.01" placeholder="Unit cost ₱" required><button type="button" class="btn ghost small remove-line" aria-label="Remove line">×</button></div></div><button type="button" class="btn secondary" id="addPurchaseLine">＋ Add another item</button><button class="btn primary full purchase-submit">Save purchase and update stock</button></form></div><div class="panel"><div class="panel-heading"><div><h3>Purchase notes</h3><p>Keep supplier invoices for reference.</p></div></div><div class="info-card"><span class="stat-icon green">✓</span><strong>Stock updates automatically</strong><p>Once saved, each received quantity is added to inventory and recorded in stock movement history.</p></div><div class="info-card"><span class="stat-icon orange">₱</span><strong>Cost tracking</strong><p>The product's current cost is updated to the latest recorded purchase cost.</p></div></div></div>
<div class="panel"><div class="panel-heading"><div><h3>Recent purchases</h3><p>Latest 100 stock receipts.</p></div></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Supplier</th><th>Received by</th><th class="align-right">Total</th></tr></thead><tbody><?php foreach($purchases as $p): ?><tr><td><strong><?= e($p['reference_no']?:'PUR-'.$p['id']) ?></strong></td><td><?= date('M j, Y g:i A',strtotime($p['purchased_at'])) ?></td><td><?= e($p['supplier']??'Not specified') ?></td><td><?= e($p['receiver']) ?></td><td class="align-right"><?= money($p['total_amount']) ?></td></tr><?php endforeach; ?><?php if(!$purchases): ?><tr><td colspan="5"><div class="empty-state compact"><strong>No purchases recorded yet</strong></div></td></tr><?php endif; ?></tbody></table></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const lines=document.getElementById('purchaseLines');const add=document.getElementById('addPurchaseLine');const template=lines.firstElementChild.cloneNode(true);add.addEventListener('click',()=>{const row=template.cloneNode(true);row.querySelectorAll('input').forEach(i=>i.value='');row.querySelector('select').selectedIndex=0;lines.appendChild(row);});lines.addEventListener('click',e=>{if(e.target.closest('.remove-line')){if(lines.children.length>1)e.target.closest('.purchase-line').remove();}});lines.addEventListener('change',e=>{if(e.target.matches('select[name="product_id[]"]')){const cost=e.target.selectedOptions[0].dataset.cost;const input=e.target.closest('.purchase-line').querySelector('input[name="unit_cost[]"]');if(cost&&!input.value)input.value=cost;}});});</script>
<?php require __DIR__.'/includes/footer.php'; ?>
